import numpy as np
from sklearn.cluster import DBSCAN

def identify_high_affinity_targets(oligos):
    features = []
    target = "GGGAGTCCT"
    for probe in oligos:
        affinity = 0
        for t_char, p_char in zip(target, probe):
            if t_char == p_char:
                affinity += 1
        features.append(affinity)
    features = np.array(features).reshape(-1, 1)
    dbscan = DBSCAN(eps=0.5, min_samples=2).fit(features)
    high_affinity_probes = []
    for probe_idx in np.where(dbscan.labels_ == 0)[0]:
        high_affinity_probes.append(oligos[probe_idx])
    return high_affinity_probes

