import os
import shutil

def deploy_files(src_dir):
    dst_dir = os.path.realpath(src_dir).replace('/src', '/deploy')

    if not os.path.exists(dst_dir):
        os.makedirs(dst_dir)

    for item in os.listdir(src_dir):
        s = os.path.join(src_dir, item)
        d = os.path.join(dst_dir, item)

        if not item.startswith('.'):
            if os.path.isfile(s):
                shutil.copy2(s, d)
            else:
                if os.path.exists(d):
                    shutil.rmtree(d)

                shutil.copytree(s, d)
                os.chmod(d, 0o777 + os.stat(dst_dir).st_mode)

deploy_files('files')

